script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnMirror = document.getElementById('btnMirrorToggle');
  var btnCapture = document.getElementById('btnCapture');
  var btnSwitchFacing = document.getElementById('btnSwitchFacing');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnMeasureFps = document.getElementById('btnMeasureFps');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var statResolution = document.getElementById('statResolution');
  var statFps = document.getElementById('statFps');
  var statFacing = document.getElementById('statFacing');
  var statDeviceName = document.getElementById('statDeviceName');
  var statMegapixels = document.getElementById('statMegapixels');
  var statAspect = document.getElementById('statAspect');
  var statHd = document.getElementById('statHd');
  var statMeasuredFps = document.getElementById('statMeasuredFps');
  var statFrameTime = document.getElementById('statFrameTime');
  var statFpsVerdict = document.getElementById('statFpsVerdict');
  var statCameraCount = document.getElementById('statCameraCount');
  var statBrightness = document.getElementById('statBrightness');
  var statLighting = document.getElementById('statLighting');
  var cmpFront = document.getElementById('cmpFront');
  var cmpRear = document.getElementById('cmpRear');

  var PAGE_FACING = 'user';
  var PAGE_LABEL = 'Front';
  var currentStream = null;
  var currentTrack = null;
  var starting = false;
  var sessionToken = 0;
  var activeFacing = PAGE_FACING;
  var selectedDeviceId = '';
  var measuring = false;
  var lastMeasured = null;
  var brightnessTimer = null;
  var canvas = document.createElement('canvas');
  var ctx = canvas.getContext('2d');
  var aCanvas = document.createElement('canvas');
  var aCtx = aCanvas.getContext('2d', { willReadFrequently: true });
  var lastPhotoUrl = null;

  // Front cameras are mirrored in the preview by long-standing convention
  // (so moving your hand right looks right, like a real mirror) but NOT in
  // the captured file, which matches what the camera actually saw -- this
  // trips people up constantly, so the mirror toggle starts ON here and
  // capture always saves the true, unmirrored frame regardless of the
  // toggle. See this tool's own content for the full explanation.
  function setMirror(mirrored) {
    previewWrap.classList.toggle('is-mirrored', mirrored);
    btnMirror.setAttribute('aria-pressed', mirrored ? 'true' : 'false');
    btnMirror.textContent = mirrored ? 'Mirror (on by default)' : 'Show Natural View';
  }
  setMirror(true);

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function gcd(a, b) { while (b) { var t = b; b = a % b; a = t; } return a; }

  function aspectLabel(w, h) {
    if (!w || !h) return '—';
    var portrait = h > w;
    var r = portrait ? h / w : w / h;
    var known = [[16, 9], [4, 3], [3, 2], [16, 10], [21, 9], [5, 4], [1, 1]];
    for (var i = 0; i < known.length; i++) {
      if (Math.abs(r - known[i][0] / known[i][1]) < 0.02) {
        return portrait ? known[i][1] + ':' + known[i][0] : known[i][0] + ':' + known[i][1];
      }
    }
    var g = gcd(w, h) || 1;
    if (w / g <= 32 && h / g <= 32) return (w / g) + ':' + (h / g);
    return r.toFixed(2) + ':1';
  }

  function standardLabel(w, h) {
    var s = Math.min(w, h);
    if (s >= 2160) return '4K UHD';
    if (s >= 1440) return '1440p QHD';
    if (s >= 1080) return '1080p Full HD';
    if (s >= 720) return '720p HD';
    if (s >= 480) return '480p SD';
    return 'Below SD';
  }

  function lightingVerdict(y) {
    if (y < 50) return 'Too dark';
    if (y < 90) return 'Dim';
    if (y <= 190) return 'Good';
    return 'Very bright';
  }

  function resetInfo() {
    [statResolution, statFps, statFacing, statDeviceName, statMegapixels, statAspect, statHd,
      statMeasuredFps, statFrameTime, statFpsVerdict, statBrightness, statLighting].forEach(function (el) {
      el.textContent = '—';
    });
    lastMeasured = null;
  }

  // Every camera page on this site copies this stopStream()/error pattern
  // from webcam-test-online.json (see this project's own CLAUDE.md).
  function stopStream() {
    sessionToken++;
    measuring = false;
    if (brightnessTimer) { clearInterval(brightnessTimer); brightnessTimer = null; }
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    currentTrack = null;
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnCapture.disabled = true;
    btnMeasureFps.disabled = true;
    resetInfo();
  }

  function describeError(err) {
    var word = activeFacing === 'user' ? 'front' : 'rear';
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Click the camera icon in your address bar (or your browser’s site settings) and allow access, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No matching camera was found.</strong> This device may not have a ' + word + '-facing camera, or the browser can’t reach it.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use.</strong> Another app or browser tab is probably holding it — close video-calling apps or other camera tabs and try again.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>No ' + word + '-facing camera could be matched.</strong> Some laptops and desktops only report one generic camera; pick it from the camera list, or try the plain <a href="/">Webcam Test</a> instead.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires a secure connection.</strong> Make sure this page is loaded over HTTPS.' };
      case 'AbortError':
        return { sev: 'warn', html: 'The camera request was interrupted. Click <strong>Start ' + PAGE_LABEL + ' Camera</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  // Shared sessionStorage keys the front/rear tools both read and write --
  // sessionStorage (not localStorage) so a comparison never persists past
  // this browser tab/session, matching the site's "nothing is stored"
  // privacy stance for anything longer-lived than the current visit.
  var REAR_KEY = 'webcamtest:rearCameraResult';
  var FRONT_KEY = 'webcamtest:frontCameraResult';

  function formatCameraResult(r) {
    return r.resolution + ' @ ' + r.fps + (r.deviceName ? ' (' + r.deviceName + ')' : '');
  }

  function readStoredResult(key) {
    try {
      var raw = sessionStorage.getItem(key);
      return raw ? JSON.parse(raw) : null;
    } catch (e) { return null; }
  }

  function renderComparison() {
    var front = readStoredResult(FRONT_KEY);
    if (front) {
      cmpFront.textContent = formatCameraResult(front);
      cmpFront.classList.remove('unsupported');
    }
    var rear = readStoredResult(REAR_KEY);
    if (rear) {
      cmpRear.textContent = formatCameraResult(rear);
      cmpRear.classList.remove('unsupported');
    }
  }

  // Results are filed under the facing the camera actually reports (or
  // the one requested), so switching lenses on this page fills both rows.
  function storeResult() {
    if (!currentTrack) return;
    var settings = currentTrack.getSettings ? currentTrack.getSettings() : {};
    var facing = settings.facingMode || (selectedDeviceId ? '' : activeFacing);
    if (facing !== 'user' && facing !== 'environment') return;
    var result = {
      resolution: statResolution.textContent,
      fps: lastMeasured ? lastMeasured.fps.toFixed(1) + ' fps measured' : statFps.textContent,
      deviceName: currentTrack.label || '',
      ts: Date.now()
    };
    try { sessionStorage.setItem(facing === 'environment' ? REAR_KEY : FRONT_KEY, JSON.stringify(result)); } catch (e) {}
    renderComparison();
  }

  function updateInfo(track) {
    var settings = track.getSettings ? track.getSettings() : {};
    var w = settings.width || video.videoWidth || 0;
    var h = settings.height || video.videoHeight || 0;
    statResolution.textContent = w && h ? (w + '×' + h) : '—';
    statFps.textContent = settings.frameRate ? (Math.round(settings.frameRate * 10) / 10 + ' fps') : '—';
    statFacing.textContent = settings.facingMode || 'Not reported';
    statDeviceName.textContent = track.label || 'Camera';
    if (w && h) {
      statMegapixels.textContent = (w * h / 1e6).toFixed(2) + ' MP';
      statAspect.textContent = aspectLabel(w, h);
      statHd.textContent = Math.min(w, h) >= 720 ? 'Pass' : 'Below 720p';
    }
    storeResult();
  }

  function populateDeviceSelect(devices) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    statCameraCount.textContent = cams.length + (cams.length === 1 ? ' camera' : ' cameras');
    deviceSelect.innerHTML = '';
    var auto = document.createElement('option');
    auto.value = '';
    auto.textContent = (activeFacing === 'user' ? 'Front' : 'Rear') + ' camera (automatic)';
    deviceSelect.appendChild(auto);
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      deviceSelect.appendChild(opt);
    });
    deviceSelect.value = selectedDeviceId;
    if (deviceSelect.value !== selectedDeviceId) deviceSelect.value = '';
    deviceSelect.disabled = cams.length === 0;
  }

  function startStream() {
    if (starting) return;
    starting = true;
    stopStream();
    var token = sessionToken;
    setDiagnostic([{ sev: '', html: 'Requesting ' + (activeFacing === 'user' ? 'front' : 'rear') + ' camera access…' }]);
    btnStart.disabled = true;

    // ideal (not exact) so a device with only one camera still gets a
    // stream instead of hard-failing -- same facingMode convention every
    // camera tool on this site uses. A camera picked from the list (e.g.
    // an external webcam) is requested by its exact deviceId instead.
    var videoConstraint = selectedDeviceId ? { deviceId: { exact: selectedDeviceId } } : { facingMode: { ideal: activeFacing } };
    navigator.mediaDevices.getUserMedia({ video: videoConstraint, audio: false })
      .then(function (stream) {
        if (token !== sessionToken) { stream.getTracks().forEach(function (t) { t.stop(); }); throw { name: 'AbortError' }; }
        currentStream = stream;
        currentTrack = stream.getVideoTracks()[0];
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function () {
        if (token !== sessionToken || !currentTrack) return null;
        updateInfo(currentTrack);
        btnStop.disabled = false;
        btnCapture.disabled = false;
        btnMeasureFps.disabled = false;
        startBrightnessLoop();
        setDiagnostic([{ sev: 'ok', html: '<strong>' + (activeFacing === 'user' ? 'Front' : 'Rear') + ' camera is live.</strong> Nothing is uploaded — this feed stays in your browser tab. Click <strong>Measure Frame Rate</strong> to count the frames it really delivers.' }]);
        return navigator.mediaDevices.enumerateDevices().then(populateDeviceSelect).catch(function () {});
      })
      .catch(function (err) {
        if (err && err.name === 'AbortError' && token !== sessionToken) return;
        setDiagnostic([describeError(err)]);
      })
      .finally(function () {
        starting = false;
        btnStart.disabled = false;
      });
  }

  // Frames counted over a fixed sample: requestVideoFrameCallback fires
  // once per delivered frame (what really matters, unlike the negotiated
  // getSettings() rate). Firefox lacks it, so fall back to its decoded-
  // frame counters.
  function measureFps(durationMs, done) {
    if (measuring || !currentStream) return;
    measuring = true;
    var token = sessionToken;
    function finish(result) {
      measuring = false;
      if (token === sessionToken) done(result);
    }
    if (typeof video.requestVideoFrameCallback === 'function') {
      var frames = 0, start = null;
      var tick = function () {
        if (token !== sessionToken) { measuring = false; return; }
        var now = performance.now();
        if (start === null) start = now; else frames++;
        if (now - start >= durationMs) {
          var secs = (now - start) / 1000;
          finish({ frames: frames, seconds: secs, fps: frames / secs });
          return;
        }
        video.requestVideoFrameCallback(tick);
      };
      video.requestVideoFrameCallback(tick);
      return;
    }
    var getCount = function () {
      if (typeof video.mozPaintedFrames === 'number') return video.mozPaintedFrames;
      if (video.getVideoPlaybackQuality) return video.getVideoPlaybackQuality().totalVideoFrames;
      return null;
    };
    var c0 = getCount();
    var t0 = performance.now();
    setTimeout(function () {
      var c1 = getCount();
      var secs = (performance.now() - t0) / 1000;
      if (c0 === null || c1 === null || c1 <= c0) { finish(null); return; }
      finish({ frames: c1 - c0, seconds: secs, fps: (c1 - c0) / secs });
    }, durationMs);
  }

  btnMeasureFps.addEventListener('click', function () {
    if (!currentStream || measuring) return;
    btnMeasureFps.disabled = true;
    setDiagnostic([{ sev: '', html: 'Counting delivered frames for 10 seconds — keep this tab visible…' }]);
    measureFps(10000, function (result) {
      btnMeasureFps.disabled = !currentStream;
      if (!result) {
        statMeasuredFps.textContent = 'Not measurable';
        setDiagnostic([{ sev: 'warn', html: 'This browser doesn’t expose a frame counter, so only the negotiated frame rate is available.' }]);
        return;
      }
      lastMeasured = result;
      statMeasuredFps.textContent = result.fps.toFixed(1) + ' fps';
      statFrameTime.textContent = (1000 / result.fps).toFixed(1) + ' ms';
      statFpsVerdict.textContent = result.fps >= 29 ? 'Smooth (30 fps class)' : (result.fps >= 24 ? 'OK (24 fps floor)' : 'Choppy (below 24)');
      setDiagnostic([{ sev: result.fps >= 24 ? 'ok' : 'warn', html: '<strong>' + result.frames + ' frames in ' + result.seconds.toFixed(1) + ' s = ' + result.fps.toFixed(1) + ' fps.</strong>' + (result.fps < 24 ? ' Dim light is the usual cause — the sensor lengthens each exposure.' : '') }]);
      storeResult();
    });
  });

  // Average brightness (0 = black, 255 = white) of a small sample of the
  // live frame, refreshed every second.
  function startBrightnessLoop() {
    if (brightnessTimer) clearInterval(brightnessTimer);
    brightnessTimer = setInterval(function () {
      if (!currentStream || !video.videoWidth) return;
      aCanvas.width = 64;
      aCanvas.height = Math.max(1, Math.round(64 * video.videoHeight / video.videoWidth));
      aCtx.drawImage(video, 0, 0, aCanvas.width, aCanvas.height);
      var d;
      try { d = aCtx.getImageData(0, 0, aCanvas.width, aCanvas.height).data; } catch (e) { return; }
      var y = 0;
      for (var i = 0; i < d.length; i += 4) y += 0.2126 * d[i] + 0.7152 * d[i + 1] + 0.0722 * d[i + 2];
      y /= d.length / 4;
      statBrightness.textContent = String(Math.round(y));
      statLighting.textContent = lightingVerdict(y);
    }, 1000);
  }

  function capturePhoto() {
    if (!currentStream) return;
    var w = video.videoWidth, h = video.videoHeight;
    if (!w || !h) return;
    canvas.width = w;
    canvas.height = h;
    // Always draws the real, unmirrored frame -- the mirror toggle only
    // applies a CSS transform to the live <video> preview, it never
    // touches the actual pixel data being drawn here.
    ctx.drawImage(video, 0, 0, w, h);
    canvas.toBlob(function (blob) {
      if (!blob) return;
      if (lastPhotoUrl) URL.revokeObjectURL(lastPhotoUrl);
      lastPhotoUrl = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = lastPhotoUrl;
      a.download = 'front-camera-photo.png';
      document.body.appendChild(a);
      a.click();
      a.remove();
    }, 'image/png');
  }

  function updateSwitchLabel() {
    btnSwitchFacing.textContent = activeFacing === 'user' ? 'Switch to Rear Camera' : 'Switch to Front Camera';
  }

  btnStart.addEventListener('click', function () {
    var changed = activeFacing !== PAGE_FACING;
    activeFacing = PAGE_FACING;
    selectedDeviceId = deviceSelect.value;
    updateSwitchLabel();
    if (changed) setMirror(true);
    startStream();
  });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped. Click <strong>Start ' + PAGE_LABEL + ' Camera</strong> to test again.' }]);
  });
  btnSwitchFacing.addEventListener('click', function () {
    activeFacing = activeFacing === 'user' ? 'environment' : 'user';
    selectedDeviceId = '';
    updateSwitchLabel();
    setMirror(activeFacing === 'user');
    startStream();
  });
  deviceSelect.addEventListener('change', function () {
    selectedDeviceId = deviceSelect.value;
    if (currentStream) startStream();
  });
  video.addEventListener('resize', function () { if (currentTrack) updateInfo(currentTrack); });
  btnMirror.addEventListener('click', function () {
    setMirror(!previewWrap.classList.contains('is-mirrored'));
  });
  btnCapture.addEventListener('click', capturePhoto);

  // Guaranteed teardown: release the camera the moment the visitor leaves
  // this page, even if they never clicked Stop.
  window.addEventListener('pagehide', function () {
    stopStream();
    if (lastPhotoUrl) { URL.revokeObjectURL(lastPhotoUrl); lastPhotoUrl = null; }
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  renderComparison();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    btnStart.disabled = true;
    btnSwitchFacing.disabled = true;
  }
})();
